/*
 * Custom energy scale for MG7, in CUDA or HIP. Generated by bin/init_custom_func.
 *
 * It is called once per phase-space point and returns
 * the renormalization and factorization scale in GeV for one phase-space
 * point. The run card scale_factor is applied on top, and fixed scales still
 * take precedence.
 *
 * Parameters:
 * particle_count  number of external particles, incoming ones first
 * pdg_ids         PDG ids of the external particles
 * momenta         momenta[i] = (E, px, py, pz) of particle i in GeV, lab frame
 *
 * Run `make` in this directory to build ../lib/custom_scale.so.
 * The function runs on the GPU, one thread per event.
 */

__device__ double custom_scale(int particle_count, const int* pdg_ids, const double momenta[][4]) {
    (void)particle_count;
    (void)pdg_ids;
    // Example: H_T / 2, the scalar sum of the final-state transverse masses.
    // double ht = 0.;
    // for (int i = 2; i < particle_count; ++i) {
    //     double e = momenta[i][0], pz = momenta[i][3];
    //     ht += sqrt(fmax(e * e - pz * pz, 0.));
    // }
    // return ht / 2.;

    // default: partonic center-of-mass energy sqrt(s_hat)
    double e = momenta[0][0] + momenta[1][0];
    double px = momenta[0][1] + momenta[1][1];
    double py = momenta[0][2] + momenta[1][2];
    double pz = momenta[0][3] + momenta[1][3];
    return sqrt(fmax(e * e - px * px - py * py - pz * pz, 0.));
}
